-- KeyForCars article master as SQL: the same 1704 cards scripts/kfc-seed-articles.mjs loads,
-- for pasting into the Supabase SQL editor when the node script cannot be run.
-- GENERATED from src/data/keyforcars-stock.json and keyforcars-prices.json.
-- Safe to run more than once: adds cards that are missing, fills a sale price only where it is
-- empty, and changes nothing else (never stock, purchase price, name, SKU or barcodes).
-- Run it BEFORE the migration bundle when the table is empty, so 0134 links the categories.
begin;
on conflict (code) do update
  set sale_price_cents = coalesce(public.kfc_articles.sale_price_cents, excluded.sale_price_cents);
commit;
select count(*) as artikelen, count(*) filter (where sale_price_cents is not null) as met_verkoopprijs from public.kfc_articles;
